  --color-primary-foreground: light-dark(#ffffff, #0f1011);
  --color-accent: light-dark(#ecebe5, #1d1e22);
  --color-accent-foreground: light-dark(#141413, #eeece6);
  --color-brand: light-dark(#4a6400, #cbf26b);
  --color-lime: #cbf26b;
  --color-ai: light-dark(#5b45c9, #b8a6ff);
  --color-ai-soft: light-dark(#f1eeff, #1a1922);
  --color-ai-border: light-dark(#d6cffb, #3d3760);
  --color-chart-out: light-dark(#a9aaa3, #5b5d62);
  --color-sidebar: light-dark(#f4f3ee, #0f1011);
  --color-success: light-dark(#3f6b00, #cbf26b);
  --color-success-soft: light-dark(#f0f7dc, #1c2410);
  --color-warning: light-dark(#a8441c, #ff9a76);
  --color-warning-soft: light-dark(#fff1ea, #2a1b14);
  --color-danger: light-dark(#b42318, #ff7a6b);
  --color-danger-soft: light-dark(#fef3f2, #2e1614);

  /* Status shades pages already use follow the theme instead of a fixed palette. */
  --color-red-700: var(--color-danger);
  --color-red-800: var(--color-danger);
  --color-red-50: var(--color-danger-soft);
  --color-amber-700: var(--color-warning);
